SELECT 
FROM dms_withdraw_record


        AND agent_id = #{agentId}


        AND status = #{status}


        AND create_time >= #{startTime}


        AND create_time <= #{endTime}


ORDER BY create_time DESC

SELECT COALESCE(SUM(CASE WHEN create_time >= #{dayStart} THEN 1 ELSE 0 END), 0) AS dailyCount,
       COUNT(*) AS monthlyCount
FROM dms_withdraw_record
WHERE agent_id = #{agentId}
  AND create_time >= #{monthStart}

SELECT id, bank_account FROM dms_withdraw_record
WHERE bank_account IS NOT NULL AND bank_account != '' AND bank_account NOT LIKE 'enc:v1:%'
ORDER BY id LIMIT #{limit}

mapper.update:
UPDATE dms_withdraw_record
SET bank_account=#{bankAccount,typeHandler=com.macro.mall.distribution.security.EncryptedStringTypeHandler}
WHERE id=#{id} AND bank_account IS NOT NULL AND bank_account != '' AND bank_account NOT LIKE 'enc:v1:%'

UPDATE dms_withdraw_record
SET status = #{status}
WHERE id = #{id}
